    t.app.all("/**", (event) => {
      return serveStatic(event, {
        getMeta: (id) => {
          if (id.includes("missing")) return undefined;
          if (id === "/app.js.gz") return { type: "text/javascript", encoding: "gzip", size: 40 };
          if (id.endsWith(".gz")) return undefined;
          if (id === "/bare.txt") return { size: 100 };
          if (id === "/nosize.txt") return { etag: "v1" };
          if (id === "/empty.txt") return { size: 0 };
          return { type: "text/plain", etag: "v1", mtime: 1_700_000_000_000, size: 100 };
        },
        getContents: (id) => {
          if (id === "/app.js.gz") return "g".repeat(40);
          if (id === "/empty.txt") return "";
          return body;
        },
        encodings: { gzip: ".gz" },
      });
    });
  });

  it("advertises byte ranges on a full GET", async () => {
    const res = await t.fetch("/file.txt");
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe(body);
  });

  it("advertises byte ranges on HEAD", async () => {
    const res = await t.fetch("/file.txt", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
  });

  it("answers a closed range with 206", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=10-19" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 10-19/100");
    expect(res.headers.get("content-length")).toBe("10");
    expect(await res.text()).toBe(body.slice(10, 20));
  });

  it("answers an open range with 206", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=90-" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 90-99/100");
    expect(res.headers.get("content-length")).toBe("10");
    expect(await res.text()).toBe(body.slice(90));
  });

  it("answers a suffix range with 206", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=-500" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/100");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe(body);
  });

  it("clamps a range end past the last byte", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-999" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/100");
    expect(await res.text()).toBe(body);
  });

  it("ignores Range with spaces around its separators", async () => {
    for (const range of ["bytes= 10-19", "bytes=10 - 19"]) {
      const res = await t.fetch("/file.txt", { headers: { range } });
      expect(res.status, range).toBe(200);
      expect(res.headers.get("content-range"), range).toBeNull();
      expect(await res.text(), range).toBe(body);
    }
  });

  it("answers HEAD with the GET range headers and no body", async () => {
    const res = await t.fetch("/file.txt", { method: "HEAD", headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-9/100");
    expect(res.headers.get("content-length")).toBe("10");
    expect(await res.text()).toBe("");
  });

  it("answers HEAD with a suffix range with 206", async () => {
    const res = await t.fetch("/file.txt", { method: "HEAD", headers: { range: "bytes=-500" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/100");
  });

  it("answers unsatisfiable ranges with 416 on GET and HEAD", async () => {
    for (const method of ["GET", "HEAD"]) {
      for (const range of ["bytes=100-200", "bytes=-0"]) {
        const res = await t.fetch("/file.txt", { method, headers: { range } });
        expect(res.status, `${method} ${range}`).toBe(416);
        expect(res.headers.get("content-range"), `${method} ${range}`).toBe("bytes */100");
        expect(res.headers.get("content-length"), `${method} ${range}`).toBe("0");
      }
    }
  });

  it("ignores malformed, unknown-unit, multi-range and reversed Range headers", async () => {
    const ranges = [
      "bytes=0-4,10-14",
      "itens=0-4",
      "bytes=abc",
      "bytes=10-5",
      "bytes=-",
      "bytes=-abc",
      "bytes=200-100",
      "bytes=0-9999999999999999999",
    ];
    for (const range of ranges) {
      const res = await t.fetch("/file.txt", { headers: { range } });
      expect(res.status, range).toBe(200);
      expect(res.headers.get("content-range"), range).toBeNull();
      expect(await res.text(), range).toBe(body);
    }
  });

  it("applies the range when If-Range matches the strong ETag", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-9", "if-range": '"v1"' },
    });
    expect(res.status).toBe(206);
  });

  it("sends the full body when If-Range does not match the ETag", async () => {
    for (const ifRange of ['"v0"', 'W/"v1"']) {
      const res = await t.fetch("/file.txt", {
        headers: { range: "bytes=0-9", "if-range": ifRange },
      });
      expect(res.status, ifRange).toBe(200);
      expect(await res.text(), ifRange).toBe(body);
    }
  });

  it("ignores an unsatisfiable range when If-Range does not match", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=500-600", "if-range": '"v0"' },
    });
    expect(res.status).toBe(200);
  });

  it("compares If-Range dates by equality with last-modified", async () => {
    const last = (await t.fetch("/file.txt")).headers.get("last-modified")!;
    const match = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-9", "if-range": last },
    });
    expect(match.status).toBe(206);

    for (const ifRange of [
      new Date(1_700_000_000_000).toISOString(),
      new Date(1_700_000_001_000).toUTCString(),
    ]) {
      const res = await t.fetch("/file.txt", {
        headers: { range: "bytes=0-9", "if-range": ifRange },
      });
      expect(res.status, ifRange).toBe(200);
    }
  });

  it("ignores If-Range when the asset has no validators", async () => {
    const res = await t.fetch("/bare.txt", {
      headers: { range: "bytes=0-9", "if-range": '"v1"' },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("answers 304 before evaluating Range", async () => {
    for (const range of ["bytes=0-9", "bytes=500-600"]) {
      const res = await t.fetch("/file.txt", {
        headers: { range, "if-none-match": '"v1"' },
      });
      expect(res.status, range).toBe(304);
      expect(res.headers.get("content-range"), range).toBeNull();
    }
  });

  it("answers 304 to If-Modified-Since before evaluating Range", async () => {
    const last = (await t.fetch("/file.txt")).headers.get("last-modified")!;
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-9", "if-modified-since": last },
    });
    expect(res.status).toBe(304);
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("applies the range to the precompressed variant", async () => {
    const res = await t.fetch("/app.js", {
      headers: { range: "bytes=0-9", "accept-encoding": "gzip" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-encoding")).toBe("gzip");
    expect(res.headers.get("content-length")).toBe("10");
    expect(res.headers.get("content-range")).toBe("bytes 0-9/40");
  });

  it("applies the range to the original when no variant exists", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-9", "accept-encoding": "gzip" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-encoding")).toBeNull();
    expect(res.headers.get("content-range")).toBe("bytes 0-9/100");
  });

  it("keeps accept-ranges on 304 and 416 responses", async () => {
    const notModified = await t.fetch("/file.txt", { headers: { "if-none-match": '"v1"' } });
    expect(notModified.headers.get("accept-ranges")).toBe("bytes");

    const unsatisfiable = await t.fetch("/file.txt", { headers: { range: "bytes=100-200" } });
    expect(unsatisfiable.headers.get("accept-ranges")).toBe("bytes");
  });

  it("keeps 404 for a range on a missing asset", async () => {
    const res = await t.fetch("/missing.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(404);
    expect(res.headers.get("accept-ranges")).toBeNull();
  });

  it("keeps 405 for a range on POST", async () => {
    const res = await t.fetch("/file.txt", { method: "POST", headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(405);
    expect(res.headers.get("allow")).toBe("GET, HEAD");
    expect(res.headers.get("accept-ranges")).toBeNull();
  });

  it("ignores Range when the size is unknown", async () => {
    const res = await t.fetch("/nosize.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(body);
  });

  it("ignores Range when the size is zero", async () => {
    const res = await t.fetch("/empty.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe("");
  });

  it("slices materialized bodies by UTF-8 bytes", async () => {
    // "é" is 2 bytes and "🙂" is 4, so the emoji is bytes 2 to 5.
    const multibyte = "é🙂";
    const bodies: Record<string, () => BodyInit> = {
      blob: () => new Blob([multibyte]),
      uint8array: () => new TextEncoder().encode(multibyte),
      arraybuffer: () => new TextEncoder().encode(multibyte).buffer,
      string: () => multibyte,
    };
    t.app.all("/types/**", (event) => {
      return serveStatic(event, {
        getMeta: () => ({ size: 6 }),
        getContents: (id) => bodies[id.slice("/types/".length)]?.(),
      });
    });

    for (const name of Object.keys(bodies)) {
      const res = await t.fetch(`/types/${name}`, { headers: { range: "bytes=2-5" } });
      expect(res.status, name).toBe(206);
      expect(res.headers.get("content-range"), name).toBe("bytes 2-5/6");
      expect(await res.text(), name).toBe("🙂");
    }
  });

  it("sends a stream in full on GET and cancels it on HEAD", async () => {
    let cancels = 0;
    t.app.all("/stream/**", (event) => {
      return serveStatic(event, {
        getMeta: () => ({ size: 100 }),
        getContents: () =>
          new ReadableStream({
            start(controller) {
              controller.enqueue(new TextEncoder().encode(body));
              controller.close();
            },
            cancel() {
              cancels++;
            },
          }),
      });
    });

    const res = await t.fetch("/stream/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(body);

    const head = await t.fetch("/stream/file.txt", {
      method: "HEAD",
      headers: { range: "bytes=0-9" },
    });
    expect(head.status).toBe(200);
    expect(cancels).toBe(1);
  });

  it("overrides a user content-length on a partial response", async () => {
    t.app.all("/clen/**", (event) => {
      return serveStatic(event, {
        getMeta: () => ({ size: 100 }),
        getContents: () => body,
        headers: { "content-length": "999" },
      });
    });

    const res = await t.fetch("/clen/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("10");
  });

  it("answers 416 with the size as content-range and not the meta size", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=100-200" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-length")).toBe("0");
    expect(res.headers.get("content-range")).toBe("bytes */100");
  });
});

