  });

  const expectedHeaders = {
    "content-type": "text/plain",
    etag: "w/123",
    "content-encoding": "utf8",
    "last-modified": new Date(1_700_000_000_000).toUTCString(),
    vary: "accept-encoding",
  };

  it("Can serve asset (GET)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(res.status).toEqual(200);
    expect(await res.text()).toBe("asset:/test.png.gz");
    expect(Object.fromEntries(res.headers)).toMatchObject(expectedHeaders);
    expect(res.headers.get("content-length")).toBe("18");
  });

  it("Can serve asset (HEAD)", async () => {
    const headRes = await t.fetch("/test.png", {
      method: "HEAD",
      headers: {
        "if-none-match": "w/456",
        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
        "accept-encoding": "gzip, br",
      },
    });

    expect(headRes.status).toEqual(200);
    expect(await headRes.text()).toBe("");
    expect(Object.fromEntries(headRes.headers)).toMatchObject(expectedHeaders);
    expect(headRes.headers.get("content-length")).toBe("18");
  });

  it("Handles cache (if-none-match)", async () => {
    const res = await t.fetch("/test.png", {
      headers: { "if-none-match": "w/123" },
    });
    expect(res.headers.get("etag")).toBe(expectedHeaders.etag);
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Handles cache (if-modified-since)", async () => {
    const res = await t.fetch("/test.png", {
      headers: {
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(304);
    expect(await res.text()).toBe("");
  });

  it("Returns 404 if not found", async () => {
    const res = await t.fetch("/404/test.png");
    expect(res.status).toEqual(404);

    const headRes = await t.fetch("/404/test.png", { method: "HEAD" });
    expect(headRes.status).toEqual(404);
  });

  it("ignores if-modified-since when a non-matching if-none-match is present (RFC 9110 §13.1.3, #1454)", async () => {
    // If-None-Match takes precedence: it does not match, so a fresh 200 must be
    // returned even though If-Modified-Since alone would have produced a 304.
    const res = await t.fetch("/test.png", {
      headers: {
        "if-none-match": "w/999",
        "if-modified-since": new Date(1_700_000_000_001).toUTCString(),
      },
    });
    expect(res.status).toEqual(200);
    expect(await res.text()).toContain("asset:/test.png");
  });

  it("Falls through to the next handler", async () => {
    const res = await t.fetch("/fallthrough/test.png");
    expect(res.status).toEqual(200);
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
  });

  it("Does not leak vary to the next handler", async () => {
    const res = await t.fetch("/fallthrough/test.png", {
      headers: { "accept-encoding": "gzip" },
    });
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
    expect(res.headers.get("vary")).toBeNull();
  });
});

describeMatrix("serve static MIME types", (t, { it, expect }) => {
  beforeEach(() => {
    const serveStaticOptions: ServeStaticOptions = {
      getContents: vi.fn((id) => `content for ${id}`),
      getMeta: vi.fn((id) => ({
        size: 10,
        path: id,
      })),
    };

    t.app.all("/**", (event) => {
      return serveStatic(event, serveStaticOptions);
    });
  });

  it("Uses custom getType function", async () => {
    const customOptions: ServeStaticOptions = {
      getContents: vi.fn(() => "content"),
      getMeta: vi.fn(() => ({ size: 10 })),
      getType: vi.fn((ext) => (ext === ".xyz" ? "application/custom" : undefined)),
    };

    t.app.all("/custom/**", (event) => {
      return serveStatic(event, customOptions);
    });

    const res = await t.fetch("/custom/file v2.xyz?query=123");
    expect(res.headers.get("content-type")).toBe("application/custom");
    expect(customOptions.getType).toHaveBeenCalledWith(".xyz");

    const res2 = await t.fetch("/custom/file.txt");
    expect(res2.headers.get("content-type")).toBe("text/plain");

    const res3 = await t.fetch("/custom/file");
    expect(res3.headers.get("content-type")).toBe(
      t.target === "web" ? null : "text/plain; charset=UTF-8",
    );
  });

  it("resolves the MIME type of an uppercase extension", async () => {
    const res = await t.fetch("/photos/IMG_0001.JPG");
    expect(res.headers.get("content-type")).toBe("image/jpeg");
  });

  it("uses the requested asset's MIME type for a precompressed variant", async () => {
    const files: Record<string, string> = {
      "/pre/app.js": "js",
      "/pre/app.js.gz": "js.gz",
      "/pre/app.js.br": "js.br",
      "/pre/style.css.gz": "css.gz",
      "/pre/docs/index.html.br": "html.br",
    };
    const options: ServeStaticOptions = {
      getContents: vi.fn((id) => files[id]),
      getMeta: vi.fn((id) => (files[id] ? { size: files[id].length } : undefined)),
      encodings: { gzip: ".gz", br: ".br" },
    };

    t.app.all("/pre/**", (event) => {
      return serveStatic(event, options);
    });

    for (const [path, acceptEncoding, body, type] of [
      ["/pre/app.js", "gzip", "js.gz", "text/javascript"],
      ["/pre/app.js", "br, gzip;q=0.5", "js.br", "text/javascript"],
      ["/pre/app.js", "identity", "js", "text/javascript"],
      ["/pre/style.css", "gzip", "css.gz", "text/css"],
      ["/pre/docs", "br", "html.br", "text/html"],
    ] as const) {
      const res = await t.fetch(path, { headers: { "accept-encoding": acceptEncoding } });
      expect(await res.text(), `${path} (${acceptEncoding})`).toBe(body);
      expect(res.headers.get("content-type"), `${path} (${acceptEncoding})`).toBe(type);
    }
  });

  it("does not overwrite a content-length already set on the response", async () => {
    // An explicit response content-length must win over the size derived from
    // meta — consistent with content-type / content-encoding / last-modified,
    // which are only set when not already present on the response.
    const options: ServeStaticOptions = {
      getContents: vi.fn(() => "content"),
      getMeta: vi.fn(() => ({ size: 18 })),
      headers: { "content-length": "999" },
    };

    t.app.all("/clen/**", (event) => {
      return serveStatic(event, options);
    });

    const res = await t.fetch("/clen/file.txt", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-length")).toBe("999");
  });

  it("serves .wasm as application/wasm", async () => {
    // `WebAssembly.instantiateStreaming()` rejects any other type
    const res = await t.fetch("/module.wasm");
    expect(res.headers.get("content-type")).toBe("application/wasm");
  });
});

describeMatrix("serve static range requests", (t, { it, expect }) => {
  // Byte N of `body` is the digit `N % 10`, so a wrong offset shows in the body.
  const body = "0123456789".repeat(10);

  beforeEach(() => {
    t.app.all("/**", (event) => {
      return serveStatic(event, {
        getMeta: (id) => {
          if (id.includes("missing")) return undefined;
          if (id === "/app.js.gz") return { type: "text/javascript", encoding: "gzip", size: 40 };
          if (id.endsWith(".gz")) return undefined;
          if (id === "/bare.txt") return { size: 100 };
          if (id === "/nosize.txt") return { etag: "v1" };
          if (id === "/empty.txt") return { size: 0 };
          return { type: "text/plain", etag: '"v1"', mtime: 1_700_000_000_000, size: 100 };
        },
        getContents: (id) => {
          if (id === "/app.js.gz") return "g".repeat(40);
          if (id === "/empty.txt") return "";
          return body;
        },
        encodings: { gzip: ".gz" },
      });
    });
  });

  it("advertises byte ranges on a full GET", async () => {
    const res = await t.fetch("/file.txt");
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe(body);
  });

  it("advertises byte ranges on HEAD", async () => {
    const res = await t.fetch("/file.txt", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
  });

  it("answers a closed range with 206", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=10-19" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 10-19/100");
    expect(res.headers.get("content-length")).toBe("10");
    expect(await res.text()).toBe(body.slice(10, 20));
  });

  it("answers an open range with 206", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=90-" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 90-99/100");
    expect(res.headers.get("content-length")).toBe("10");
    expect(await res.text()).toBe(body.slice(90));
  });

  it("answers a suffix range with 206", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=-500" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/100");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe(body);
  });

  it("clamps a range end past the last byte", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-999" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/100");
    expect(await res.text()).toBe(body);
  });

  it("ignores Range with spaces around its separators", async () => {
    for (const range of ["bytes= 10-19", "bytes=10 - 19"]) {
      const res = await t.fetch("/file.txt", { headers: { range } });
      expect(res.status, range).toBe(200);
      expect(res.headers.get("content-range"), range).toBeNull();
      expect(await res.text(), range).toBe(body);
    }
  });

  it("answers HEAD with the GET range headers and no body", async () => {
    const res = await t.fetch("/file.txt", { method: "HEAD", headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-9/100");
    expect(res.headers.get("content-length")).toBe("10");
    expect(await res.text()).toBe("");
  });

  it("answers HEAD with a suffix range with 206", async () => {
    const res = await t.fetch("/file.txt", { method: "HEAD", headers: { range: "bytes=-500" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/100");
  });

  it("answers unsatisfiable ranges with 416 on GET and HEAD", async () => {
    for (const method of ["GET", "HEAD"]) {
      for (const range of ["bytes=100-200", "bytes=-0"]) {
        const res = await t.fetch("/file.txt", { method, headers: { range } });
        expect(res.status, `${method} ${range}`).toBe(416);
        expect(res.headers.get("content-range"), `${method} ${range}`).toBe("bytes */100");
        expect(res.headers.get("content-length"), `${method} ${range}`).toBe("0");
      }
    }
  });

  it("ignores malformed, unknown-unit, multi-range and reversed Range headers", async () => {
    const ranges = [
      "bytes=0-4,10-14",
      "itens=0-4",
      "bytes=abc",
      "bytes=10-5",
      "bytes=-",
      "bytes=-abc",
      "bytes=200-100",
      "bytes=0-9999999999999999999",
    ];
    for (const range of ranges) {
      const res = await t.fetch("/file.txt", { headers: { range } });
      expect(res.status, range).toBe(200);
      expect(res.headers.get("content-range"), range).toBeNull();
      expect(await res.text(), range).toBe(body);
    }
  });

  it("applies the range when If-Range matches the strong ETag", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-9", "if-range": '"v1"' },
    });
    expect(res.status).toBe(206);
  });

  it("sends the full body when If-Range does not match the ETag", async () => {
    for (const ifRange of ['"v0"', 'W/"v1"']) {
      const res = await t.fetch("/file.txt", {
        headers: { range: "bytes=0-9", "if-range": ifRange },
      });
      expect(res.status, ifRange).toBe(200);
      expect(await res.text(), ifRange).toBe(body);
    }
  });

  it("ignores an unsatisfiable range when If-Range does not match", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=500-600", "if-range": '"v0"' },
    });
    expect(res.status).toBe(200);
  });

  it("compares If-Range dates by equality with last-modified", async () => {
    const last = (await t.fetch("/file.txt")).headers.get("last-modified")!;
    const match = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-9", "if-range": last },
    });
    expect(match.status).toBe(206);

    for (const ifRange of [
      new Date(1_700_000_000_000).toISOString(),
      new Date(1_700_000_001_000).toUTCString(),
    ]) {
      const res = await t.fetch("/file.txt", {
        headers: { range: "bytes=0-9", "if-range": ifRange },
      });
      expect(res.status, ifRange).toBe(200);
    }
  });

  it("ignores If-Range when the asset has no validators", async () => {
    const res = await t.fetch("/bare.txt", {
      headers: { range: "bytes=0-9", "if-range": '"v1"' },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("answers 304 before evaluating Range", async () => {
    for (const range of ["bytes=0-9", "bytes=500-600"]) {
      const res = await t.fetch("/file.txt", {
        headers: { range, "if-none-match": '"v1"' },
      });
      expect(res.status, range).toBe(304);
      expect(res.headers.get("content-range"), range).toBeNull();
    }
  });

  it("answers 304 to If-Modified-Since before evaluating Range", async () => {
    const last = (await t.fetch("/file.txt")).headers.get("last-modified")!;
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-9", "if-modified-since": last },
    });
    expect(res.status).toBe(304);
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("applies the range to the precompressed variant", async () => {
    const res = await t.fetch("/app.js", {
      headers: { range: "bytes=0-9", "accept-encoding": "gzip" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-encoding")).toBe("gzip");
    expect(res.headers.get("content-length")).toBe("10");
    expect(res.headers.get("content-range")).toBe("bytes 0-9/40");
  });

  it("applies the range to the original when no variant exists", async () => {
    const res = await t.fetch("/file.txt", {
      headers: { range: "bytes=0-9", "accept-encoding": "gzip" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-encoding")).toBeNull();
    expect(res.headers.get("content-range")).toBe("bytes 0-9/100");
  });

  it("keeps accept-ranges on 304 and 416 responses", async () => {
    const notModified = await t.fetch("/file.txt", { headers: { "if-none-match": '"v1"' } });
    expect(notModified.headers.get("accept-ranges")).toBe("bytes");

    const unsatisfiable = await t.fetch("/file.txt", { headers: { range: "bytes=100-200" } });
    expect(unsatisfiable.headers.get("accept-ranges")).toBe("bytes");
  });

  it("keeps 404 for a range on a missing asset", async () => {
    const res = await t.fetch("/missing.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(404);
    expect(res.headers.get("accept-ranges")).toBeNull();
  });

  it("keeps 405 for a range on POST", async () => {
    const res = await t.fetch("/file.txt", { method: "POST", headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(405);
    expect(res.headers.get("allow")).toBe("GET, HEAD");
    expect(res.headers.get("accept-ranges")).toBeNull();
  });

  it("ignores Range when the size is unknown", async () => {
    const res = await t.fetch("/nosize.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(body);
  });

  it("ignores Range when the size is zero", async () => {
    const res = await t.fetch("/empty.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe("");
  });

  it("slices materialized bodies by UTF-8 bytes", async () => {
    // "é" is 2 bytes and "🙂" is 4, so the emoji is bytes 2 to 5.
    const multibyte = "é🙂";
    const bodies: Record<string, () => BodyInit> = {
      blob: () => new Blob([multibyte]),
      uint8array: () => new TextEncoder().encode(multibyte),
      arraybuffer: () => new TextEncoder().encode(multibyte).buffer,
      string: () => multibyte,
    };
    t.app.all("/types/**", (event) => {
      return serveStatic(event, {
        getMeta: () => ({ size: 6 }),
        getContents: (id) => bodies[id.slice("/types/".length)]?.(),
      });
    });

    for (const name of Object.keys(bodies)) {
      const res = await t.fetch(`/types/${name}`, { headers: { range: "bytes=2-5" } });
      expect(res.status, name).toBe(206);
      expect(res.headers.get("content-range"), name).toBe("bytes 2-5/6");
      expect(await res.text(), name).toBe("🙂");
    }
  });

  it("sends a stream in full on GET and cancels it on HEAD", async () => {
    let cancels = 0;
    t.app.all("/stream/**", (event) => {
      return serveStatic(event, {
        getMeta: () => ({ size: 100 }),
        getContents: () =>
          new ReadableStream({
            start(controller) {
              controller.enqueue(new TextEncoder().encode(body));
              controller.close();
            },
            cancel() {
              cancels++;
            },
          }),
      });
    });

    const res = await t.fetch("/stream/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(body);

    const head = await t.fetch("/stream/file.txt", {
      method: "HEAD",
      headers: { range: "bytes=0-9" },
    });
    expect(head.status).toBe(200);
    expect(cancels).toBe(1);
  });

  it("overrides a user content-length on a partial response", async () => {
    t.app.all("/clen/**", (event) => {
      return serveStatic(event, {
        getMeta: () => ({ size: 100 }),
        getContents: () => body,
        headers: { "content-length": "999" },
      });
    });

    const res = await t.fetch("/clen/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("10");
  });

  it("answers 416 with the size as content-range and not the meta size", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=100-200" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-length")).toBe("0");
    expect(res.headers.get("content-range")).toBe("bytes */100");
  });

  it("lets a range on a missing asset fall through when fallthrough is set", async () => {
    t.app.use((event) => {
      return serveStatic(event, {
        getMeta: () => undefined,
        getContents: () => body,
        fallthrough: true,
      });
    });
    t.app.use(() => "next");

    const res = await t.fetch("/file.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("next");
  });
});

describe("serve static (malformed url)", () => {
  it("falls through on a malformed `%` instead of throwing", async () => {
    // With `allowMalformedURL`, a raw malformed `%` (e.g. `/foo%`) reaches
    // serveStatic and the final `decodeURI` would throw a URIError — a 500 that
    // bypasses `fallthrough`. The guarded decode falls back to the resolved id
    // so `fallthrough` (and 404 when off) are reached as normal.
    const options: ServeStaticOptions = {
      getContents: () => undefined,
      getMeta: () => undefined,
    };

    const fallthroughApp = new H3({ allowMalformedURL: true })
      .use((event) => serveStatic(event, { ...options, fallthrough: true }))
      .use(() => "next");
    const res = await fallthroughApp.request("/foo%");
    expect(res.status).toBe(200);
    expect(await res.text()).toBe("next");

    const notFoundApp = new H3({ allowMalformedURL: true }).all("/**", (event) =>
      serveStatic(event, options),
    );
    const res404 = await notFoundApp.request("/foo%");
    expect(res404.status).toBe(404);
  });

  it("never hands a raw backslash or bare `..` to the backend under allowMalformedURL", async () => {
    // Defense-in-depth guard for the trickiest input we could construct: a
    // malformed `%` (forcing the raw pathname) whose segment is popped by a
    // `..`, leaving single-encoded `%5c` separators. If the on-disk decode
    // (`%5c` → `\`) were not neutralized, the id would become
    // `/..\..\windows\win.ini` — a traversal above the root on backslash-aware
    // (e.g. Windows) filesystem backends. It is neutralized because serveStatic
    // re-resolves dot segments *after* that decode. The event layer cannot help
    // here: canonicalization never decodes a separator (and is skipped entirely
    // for a malformed path), so `%5c` reaches serveStatic in its wire form.
    let servedId: string | undefined;
    const app = new H3({ allowMalformedURL: true }).all("/**", (event) =>
      serveStatic(event, {
        getContents: (id) => {
          servedId = id;
          return `asset:${id}`;
        },
        getMeta: () => ({ size: 1 }),
      }),
    );

    const res = await app.request("/a%ZZ/../..%5c..%5cwindows%5cwin.ini");
    expect(res.status).toBe(200);
    expect(servedId).toBeDefined();
    expect(servedId).not.toContain("\\"); // no raw backslash separator
    expect(servedId).not.toMatch(/(^|[\\/])\.\.([\\/]|$)/); // no bare `..` segment
  });
});

